description:
Use template literal types to build an `EventMap<T>` that maps `'change:<key>'` event names to the value type of that key in `T`.

**Example:**
```ts
type Config = { host: string; port: number };
type Events = EventMap<Config>;
// { 'change:host': string; 'change:port': number }
```

Also implement `on<T>(event: keyof EventMap<T>, handler: (val: EventMap<T>[typeof event]) => void)` — typed event listener.

starter_code:
export type EventMap<T> = // your type here

export function on<T>(
  _obj: T,
  event: keyof EventMap<T>,
  handler: (val: EventMap<T>[keyof EventMap<T>]) => void
) {
  // runtime impl not required — type correctness is the goal
  void event; void handler;
}

test_suite:
test('EventMap maps change:key to value type', () => {
  type Config = { host: string; port: number };
  type Events = EventMap<Config>;
  type HostEvent = Events['change:host'];
  const check: HostEvent = 'localhost';
  expect(check).toBe('localhost');
});

test('EventMap includes all keys', () => {
  type Config = { a: number; b: boolean };
  type Keys = keyof EventMap<Config>;
  const k1: Keys = 'change:a';
  const k2: Keys = 'change:b';
  expect(k1).toBe('change:a');
  expect(k2).toBe('change:b');
});

test('on function accepts correct event names', () => {
  const cfg = { host: 'localhost', port: 8080 };
  expect(() => on(cfg, 'change:host', (v) => { const s: string = v; void s; })).not.toThrow();
});

// __hidden__
test('EventMap port event is number type', () => {
  type Config = { port: number };
  type PortEvent = EventMap<Config>['change:port'];
  const check: PortEvent = 3000;
  expect(check).toBe(3000);
});

solution:
export type EventMap<T> = {
  [K in keyof T & string as `change:${K}`]: T[K]
};

export function on<T>(
  _obj: T,
  event: keyof EventMap<T>,
  handler: (val: EventMap<T>[keyof EventMap<T>]) => void
) {
  void event; void handler;
}
